head.script:
scwin.btn_search_onclick = function () {
    $c.sbm.execute(sbm_search);
};

scwin.btn_detail_onclick = function () {
    $p.executeSubmission("sbm_detail");
};

scwin.btn_save_onclick = function () {
    $c.sbm.execute(sbm_nomethod, { data: 1 });
};

scwin.loadCodes = function () {
    const option = { id: "sbm_codes", action: "/common/codes", method: "post" };
    $c.sbm.executeDynamic(option, {});
};

scwin.btn_missing_onclick = function () {
    $c.sbm.execute(sbm_nowhere);
};

scwin.btn_popup_onclick = function () {
    $c.win.openPopup("/ui/SP/SP002.xml", { width: 400 });
};

scwin.readConfig = function () {
    return WebSquare.core.getConfiguration("/WebSquare/processMsg/@value");
};
